import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.D_oV6oLV.js";const p=JSON.parse('{"title":"Writing docs people can read","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/writing-docs.md","filePath":"docs/agents/writing-docs.md"}'),i={name:"docs/agents/writing-docs.md"};function s(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="writing-docs-people-can-read" tabindex="-1">Writing docs people can read <a class="header-anchor" href="#writing-docs-people-can-read" aria-label="Permalink to &quot;Writing docs people can read&quot;">​</a></h1><p>A page is good when a reader finds what they came for in under a minute and can stop reading at any point without missing something they needed. Every page in <code>docs/</code> follows these rules. Agents and humans alike.</p><h2 id="the-rules" tabindex="-1">The rules <a class="header-anchor" href="#the-rules" aria-label="Permalink to &quot;The rules&quot;">​</a></h2><ol><li><strong>Open with the point.</strong> The first paragraph says what the page is about and why someone would read it, in two or three sentences. No history, no tracking issue.</li><li><strong>One idea per section.</strong> The heading names the idea (<code>Who can open it</code>, not <code>Security</code>). If a section needs &quot;also&quot;, it is two sections.</li><li><strong>Say it once, where it belongs.</strong> Other pages link instead of repeating. Never copy what the code, the OpenAPI document or a test already holds: route lists, field lists and status codes go there, and the page links to them.</li><li><strong>Explain a term before using it.</strong> Use the words of <a href="./../../CONTEXT"><code>CONTEXT.md</code></a>. If a word is new to the reader, define it in a clause at its first use, or link it.</li><li><strong>Write what and why, not how it is wired.</strong> The reader wants behaviour and the reason for it. Class names and file names appear only when the reader will go looking for them.</li><li><strong>Keep paragraphs short.</strong> Three sentences is typical, five is the limit. Use a bullet list for parallel items, a table for a lookup, prose for reasoning. No chains of clauses joined by semicolons.</li><li><strong>Fold the reference.</strong> Detail that only some readers need goes in a <code>&lt;details&gt;&lt;summary&gt;…&lt;/summary&gt;</code> block, closed by default. It works on GitHub and on the site.</li><li><strong>One audience per page.</strong> Rules and behaviour (business) go on one page, wiring and class names (technical) on another that links back. A reader should never need to skip lines to find theirs. On the site, business pages go in the <strong>Product</strong> menu and technical ones in <strong>Technical</strong> (<code>site/.vitepress/config.mts</code>).</li><li><strong>Leave out what isn&#39;t true yet.</strong> No &quot;what comes next&quot; lists and no work-in-progress notes: those belong in issues and the <a href="./../roadmap">roadmap</a>.</li></ol><h2 id="wording" tabindex="-1">Wording <a class="header-anchor" href="#wording" aria-label="Permalink to &quot;Wording&quot;">​</a></h2><p>Plain, active and specific: &quot;The server refuses it&quot; beats &quot;It is refused&quot;. Name who does what. Prefer a short word to a long one. Write the way you would explain it to a colleague at a whiteboard.</p><h2 id="before-you-finish-a-page" tabindex="-1">Before you finish a page <a class="header-anchor" href="#before-you-finish-a-page" aria-label="Permalink to &quot;Before you finish a page&quot;">​</a></h2><ul><li>Could someone say in one sentence what the page is for after reading its first paragraph?</li><li>Is any paragraph longer than five sentences, or any page longer than about 150 lines? Split it or cut it.</li><li>Is anything here also written somewhere else? Keep one, link the other.</li><li>Is every route, status code or field list one the OpenAPI document already has? Delete it and link.</li></ul><p><a href="./../admin">The admin area</a> and <a href="./../admin-internals">Admin internals</a> are the worked example.</p>',9)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
